const verifySource=`// Replays only the recorded, zero-capture actual history; rejects any capture or inconsistent snapshot.
// No hypothetical sequences, move generation, selection or recommendation.
module.exports = log => {
 const cols="ABCDEFGHJ", board={},moves=[],checks=[];
 for(let y=1;y<=9;y++)for(const c of cols)board[c+y]=".";
 const nb=p=>{const x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,z])=>a>=0&&a<9&&z>=1&&z<=9).map(([a,z])=>cols[a]+z);};
 const live=()=>{const seen=new Set();for(const p of Object.keys(board)){if(board[p]==="."||seen.has(p))continue;const q=[p],libs=new Set();seen.add(p);while(q.length){const u=q.pop();for(const v of nb(u)){if(board[v]===".")libs.add(v);else if(board[v]===board[u]&&!seen.has(v)){seen.add(v);q.push(v);}}}if(!libs.size)throw Error("Zero-liberty group in actual history");}};
 for(const call of log.calls){
  const s=call.result.content.filter(x=>x.type==="text").map(x=>x.text).join("\\n");
  if(call.kind==="play"){
   const own=/You played ([A-J][1-9])\\./.exec(s);if(!own&&!s.includes("You passed."))throw Error("Refused or unparsed actual move");
   if((own?own[1]:"pass")!==call.move)throw Error("Requested/recorded move mismatch");
   const opp=/Your opponent played ([A-J][1-9])\\./.exec(s);if(!opp&&!s.includes("Your opponent passed."))throw Error("Unparsed opponent move");
   for(const [color,point] of [["B",call.move],["W",opp?opp[1]:"pass"]]){
    moves.push({number:moves.length+1,color,point});if(point!=="pass"){if(board[point]!==".")throw Error("Repeated occupied placement");board[point]=color==="B"?"X":"O";live();}
   }
  }
  const snap={};for(const l of s.split("\\n")){const m=l.match(/^\\s*([1-9])\\s+([XO.](?:\\s+[XO.]){8})\\s+[1-9]\\s*$/);if(m)m[2].split(/\\s+/).forEach((v,x)=>snap[cols[x]+m[1]]=v);}
  if(Object.keys(snap).length!==81)throw Error("Incomplete board");
  for(const p of Object.keys(board))if(board[p]!==snap[p])throw Error("Board mismatch "+p);
  const cap=/Captured by Black: (\\d+); by White: (\\d+)/.exec(s),num=/Move number: (\\d+)/.exec(s),ko=/Ko point: ([^.]+)\\./.exec(s);
  if(!cap||+cap[1]||+cap[2])throw Error("Replay is restricted to verified zero captures");
  if(!num||+num[1]!==moves.length+1)throw Error("Move number mismatch");
  if(!ko||ko[1]!=="none")throw Error("Unexpected ko marker");
  checks.push({kind:call.kind,actualMoves:moves.length,boardMatched:true,captures:{Black:0,White:0},ko:"none"});
 }
 const stones={Black:0,White:0};for(const v of Object.values(board)){if(v==="X")stones.Black++;if(v==="O")stones.White++;}
 return {moves,checks,moveCount:moves.length,boardChecks:checks.length,finalStones:stones,allMatched:true};
};`;
store("verify69source",verifySource);
const mod={exports:null};new Function("module",verifySource)(mod);const ver=mod.exports({calls:load("g69calls")});store("verify69",ver);text(ver);
